            <div class="min-w-0"><p class="text-xs font-bold tracking-widest text-cyan-700">{{ __('contracts.title') }} · GSB EV</p><h2 id="contract-detail-title" class="mt-1 truncate text-xl font-bold text-slate-950" x-text="opportunity?.site_name || @js(__('contracts.detail_title'))"></h2><p class="mt-1 text-xs text-slate-500" x-text="opportunity?.site_code || ''"></p></div>
            <button type="button" class="rounded-xl border border-slate-200 px-3 py-2 text-slate-600 hover:bg-slate-50" @click="close()" aria-label="{{ __('contracts.close') }}">✕</button>
