            <button type="button" role="tab" :aria-selected="section === 'files'" @click="section = 'files'" class="rounded-xl px-4 py-2 text-sm font-semibold" :class="section === 'files' ? 'bg-cyan-700 text-white' : 'bg-slate-100 text-slate-600'">{{ __('contracts.files_tab') }}</button>
        </div>
