                <div x-show="section === 'details'" class="space-y-5">
                    <div class="flex flex-wrap items-center justify-between gap-3"><p class="text-xs text-slate-500" x-text="business?._source === 'current' ? @js(__('contracts.current_source')) : @js(__('contracts.legacy_source'))"></p>@if(auth()->user()->hasPermission('pipeline.business'))<button type="button" x-show="!editing" @click="startEdit()" class="rounded-xl bg-cyan-700 px-4 py-2 text-sm font-semibold text-white hover:bg-cyan-800">{{ __('contracts.edit') }}</button>@endif</div>
                    <div x-show="!editing" class="grid gap-3 sm:grid-cols-2"><template x-for="field in displayFields" :key="field.key"><div class="rounded-2xl border border-slate-200 bg-white p-4"><dt class="text-xs text-slate-500" x-text="field.label"></dt><dd class="mt-1 break-words font-semibold text-slate-950" x-text="display(business?.[field.key])"></dd></div></template></div>
                    <form x-show="editing" @submit.prevent="save()" class="space-y-4 rounded-2xl border border-slate-200 bg-white p-5"><div class="grid gap-4 sm:grid-cols-2"><template x-for="field in editFields" :key="field.key"><label class="block text-sm font-medium text-slate-700"><span x-text="field.label"></span><input :type="field.key === 'contract_expiry' ? 'date' : 'text'" x-model="form[field.key]" class="mt-1 block w-full rounded-xl border-slate-200 bg-white text-sm"></label></template></div><div x-show="saveError" role="alert" class="rounded-xl bg-rose-50 p-3 text-sm text-rose-700"><p x-text="saveError"></p><button type="button" x-show="saveError.includes(@js(__('contracts.reload')))" @click="reloadLatest()" class="mt-2 font-semibold underline">{{ __('contracts.reload') }}</button></div><div class="flex flex-wrap justify-end gap-2"><button type="button" @click="cancelEdit()" class="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">{{ __('contracts.cancel') }}</button><button type="submit" :disabled="saving" class="rounded-xl bg-gradient-to-r from-teal-600 to-cyan-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" x-text="saving ? @js(__('contracts.saving')) : @js(__('contracts.save'))"></button></div></form>
                </div>
                <div x-show="section === 'files'" class="space-y-3"><p class="text-xs text-slate-500">{{ __('contracts.legacy_file_note') }}</p><p x-show="attachments.length === 0" class="rounded-2xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500">{{ __('contracts.no_file') }}</p><template x-for="file in attachments" :key="`${file.origin}-${file.id}`"><div class="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-white p-4"><div class="min-w-0"><p class="break-all font-semibold text-slate-950" x-text="file.file_name || @js(__('contracts.unnamed_file'))"></p><p class="mt-1 text-xs text-slate-500" x-text="file.origin === 'current' ? @js(__('contracts.uploaded_current')) : @js(__('contracts.legacy_file_data'))"></p></div><a x-show="file.content_url" :href="file.content_url" class="text-sm font-semibold text-cyan-700 hover:underline">{{ __('contracts.open_file') }}</a></div></template></div>
                <a :href="pipelineUrl()" class="inline-flex text-sm font-semibold text-cyan-700 hover:underline">{{ __('contracts.related_opportunity') }}</a>
